using namespace std;

int main()
{
    int n, m;
    cin >> n;
    vector<int> first(n);
    for (int i = 0; i < n; ++i)
        cin >> first[i];

    cin >> m;
    vector<int> second(m);
    for (int i = 0; i < m; ++i)
        cin >> second[i];

    // Initialize the dp table
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

    // Fill the dp table using dynamic programming
    for (int i = 1; i <= n; ++i)
    {
        for (int j = 1; j <= m; ++j)
        {
            if (first[i - 1] == second[j - 1])
                dp[i][j] = dp[i - 1][j - 1] + 1;
            else
                dp[i][j] = max(dp[i][j - 1], dp[i - 1][j]);
        }
    }

    // The answer is stored in dp[n][m]
    cout << dp[n][m] << endl;
    return 0;
}
