import os
from PIL import Image
import imagehash

def delete_similar_images(folder, similarity_threshold=5):
    image_hashes = {}
    for root, dirs, files in os.walk(folder):
        for file in files:
            if file.lower().endswith(('.png', '.jpg', '.jpeg', '.gif', '.bmp')):
                file_path = os.path.join(root, file)
                try:
                    with Image.open(file_path) as image:
                        img_hash = imagehash.average_hash(image)

                        # Deleting similar images
                        for saved_hash in image_hashes.values():
                            if abs(img_hash - saved_hash) <= similarity_threshold:
                                os.remove(file_path)
                                print(f"Deleted: {file_path}")
                                break
                        else:
                            image_hashes[file_path] = img_hash

                except Exception as e:
                    print(f"Error processing {file_path}: {e}")

# Replace 'your_directory_path' with the path of the directory you want to process
# Adjust the similarity_threshold to your desired level of similarity (lower value = more similar)
