To create a Binary Search Tree (BST) using the Selection Sort algorithm, you can sort the data using Selection Sort first, and then insert the sorted data into the BST. However, it's worth mentioning that this is not the typical or efficient way to build a BST. The general idea of using Selection Sort is to find the minimum element in the data and put it in the first position, and then find the next minimum element and put it in the next position, and so on. The running time of Selection Sort is O(n^2).

Here is a C++ code to first sort the data using Selection Sort and then insert the sorted data into the BST:

```cpp
#include <iostream>
#include <vector>

class Node {
public:
    int key;
    Node* left;
    Node* right;

    Node(int key): key(key), left(nullptr), right(nullptr) {}
};

class BST {
private:
    Node* root;

    Node* insert(Node* node, int key) {
        if (node == nullptr) {
            return new Node(key);
        }

        if (key < node->key) {
            node->left = insert(node->left, key);
        } else {
            node->right = insert(node->right, key);
        }

        return node;
    }

public:
    BST(): root(nullptr) {}

    void insert(int key) {
        root = insert(root, key);
    }
};

void selectionSort(std::vector<int>& data) {
    for (size_t i = 0; i < data.size(); i++) {
        size_t minIndex = i;
        for (size_t j = i + 1; j < data.size(); j++) {
            if (data[j] < data[minIndex]) {
                minIndex = j;
            }
        }
        std::swap(data[i], data[minIndex]);
    }
}

int main() {
    std::vector<int> data = {5, 3, 8, 1, 7, 2, 9};

    // Sort the data using Selection Sort
    selectionSort(data);

    // Create a BST using the sorted data
    BST bst;
    for (int value : data) {
        bst.insert(value);
    }

    return 0;
}
```

However, as mentioned earlier, this approach isn't efficient when it comes to building a BST tree. Sorting the input data with the Selection Sort algorithm increases the BST building time complexity from O(n*log(n)) to O(n^2).

