To control the size/quality of a PNG image, you can change the compression level in the method. Here's an updated version of the `ImageToByteArray` method that lets you set a custom compression level between 0 and 9 for PNG images, where 0 means no compression and 9 means maximum compression.

```csharp
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;

public static byte[] ImageToByteArray(Image image, ImageFormat format, long quality = 100)
{
    if (format != ImageFormat.Png && format != ImageFormat.Jpeg)
    {
        throw new ArgumentException("Only PNG and JPEG formats are supported.");
    }

    using (var ms = new MemoryStream())
    {
        if (format == ImageFormat.Jpeg)
        {
            // Set JPEG quality
            var encoderParameters = new EncoderParameters(1);
            encoderParameters.Param[0] = new EncoderParameter(Encoder.Quality, quality);
            var jpegCodecInfo = GetEncoderInfo(ImageFormat.Jpeg);

            image.Save(ms, jpegCodecInfo, encoderParameters);
        }
        else // PNG
        {
            // Set PNG compression level
            var encoderParameters = new EncoderParameters(1);
            // Convert quality to a compression level between 0 and 9
            int compressionLevel = Math.Max(0, Math.Min(9, (int)((100 - quality) / 11)));
            encoderParameters.Param[0] = new EncoderParameter(Encoder.Compression, compressionLevel);
            var pngCodecInfo = GetEncoderInfo(ImageFormat.Png);

            image.Save(ms, pngCodecInfo, encoderParameters);
        }

        return ms.ToArray();
    }
}

private static ImageCodecInfo GetEncoderInfo(ImageFormat format)
{
    ImageCodecInfo[] codecs = ImageCodecInfo.GetImageDecoders();

    foreach (ImageCodecInfo codec in codecs)
    {
        if (codec.FormatID == format.Guid)
        {
            return codec;
        }
    }

    return null;
}
```

Now you can set a custom quality for both JPEG and PNG images by providing the quality value between 0 and 100. Note that for PNG, the quality value is translated to a compression level between 0 and 9, where 0 means no compression and 9 means the maximum compression.

