        @Override
        protected Void doInBackground(String... params) {
            try {
                // Connect to the Raspberry Pi using SSH
                JSch jsch = new JSch();
                Session session = jsch.getSession("username", wifiModuleIp, wifiModulePort);
                session.setPassword("password");

                // Set HostKey
