A more general and correct method to compute the minor of a matrix would be like this:

```cpp
#include <vector>

typedef double value_t;

std::vector<std::vector<value_t>> getMatrixMinor(const std::vector<std::vector<value_t>>& mat, std::size_t row, std::size_t col) {
    std::size_t numRows = mat.size();
    std::size_t numCols = mat[0].size();
    std::vector<std::vector<value_t>> minorMat(numRows - 1, std::vector<value_t>(numCols - 1));

    std::size_t newRow = 0;
    for (std::size_t i = 0; i < numRows; ++i) {
        if (i == row) continue;

        std::size_t newCol = 0;
        for (std::size_t j = 0; j < numCols; ++j) {
            if (j == col) continue;

            minorMat[newRow][newCol] = mat[i][j];
            ++newCol;
        }

        ++newRow;
    }

    return minorMat;
}
