use nix::sys::signal::{sigaction, SaFlags, SigAction, SigHandler, SigSet};
use nix::sys::wait;
use nix::unistd::{fork, ForkResult, getpid, setsid};
use std::process;

fn main() {
    // Catch signals
    let sigset = SigSet::empty();
    let sig_action = SigAction::new(
        SigHandler::Handler(handle_signal),
        SaFlags::SA_RESTART,
        sigset,
    );

    unsafe {
        sigaction(nix::sys::signal::Signal::SIGCHLD, &sig_action).unwrap();
    }

    // Daemonize process
    match fork() {
        Ok(ForkResult::Parent { .. }) => {
            process::exit(0);
        }
        Ok(ForkResult::Child) => {
            let _ = setsid().expect("Failed to create a new session");
